import pytest

from app import app


@pytest.fixture
def client():
    app.config["TESTING"] = True
    with app.test_client() as c:
        yield c


def test_healthz(client):
    assert client.get("/healthz").get_json() == {"status": "ok"}


def test_login_rejects_bad_email(client):
    r = client.post("/login", json={"email": "nope", "password": "longenough"})
    assert r.status_code == 400
    assert r.get_json()["error"] == "invalid_email"


def test_login_rejects_short_password(client):
    r = client.post("/login", json={"email": "a@b.co", "password": "short"})
    assert r.status_code == 400
